cat > /workspace/src/main.rs << 'EOFMAIN'
use std::env;
use std::process;
use std::io::Write;

mod args;

use args::{Arguments, ParseError};

fn main() {
    let cli_args: Vec<String> = env::args().collect();

    // If no args given, print help and exit with code 2
    if cli_args.len() == 1 {
        print_help(&cli_args[0]);
        process::exit(2);
    }

    match Arguments::parse(&cli_args) {
        Ok(args) => {
            if args.help {
                print_help(&cli_args[0]);
                process::exit(0);
            }
            if args.version {
                println!("Dirble 1.4.2 (commit d520c82, build 2026-04-17)");
                process::exit(0);
            }

            // Run the actual scanner
            if let Err(e) = run_scanner(&args) {
                eprintln!("{}", e);
                process::exit(1);
            }
        }
        Err(e) => {
            let stderr = std::io::stderr();
            let _ = writeln!(stderr.lock(), "error: {}", e);
            let _ = writeln!(stderr.lock());

            match e {
                ParseError::UnexpectedArgument(ref arg) => {
                    let _ = writeln!(stderr.lock(), "  tip: to pass '{}' as a value, use '-- {}'", arg, arg);
                }
                _ => {}
            }

            let _ = writeln!(stderr.lock());
            print_help_short(&cli_args[0]);
            process::exit(2);
        }
    }
}

fn run_scanner(args: &Arguments) -> Result<(), String> {
    // Check if we have any URIs to scan
    if args.uris.is_empty() && args.uri_file.is_none() {
        return Err("[ERROR] Unable to find host to scan".to_string());
    }

    // Check for wordlist
    if args.wordlist.is_none() {
        // Try to find default wordlist
        let default_paths = vec![
            "dirble_wordlist.txt",
            "./dirble_wordlist.txt",
            "/usr/share/dirble/dirble_wordlist.txt",
        ];

        let has_wordlist = default_paths.iter().any(|p| {
            std::path::Path::new(p).exists()
        });

        if !has_wordlist {
            return Err("[ERROR] Unable to find default wordlist".to_string());
        }
    }

    Ok(())
}

fn print_help_short(prog_name: &str) {
    println!("Usage: {} [OPTIONS] <uri|--uri-file <uri-file>|--uri <uri>>

For more information, try '--help'.", prog_name);
}

fn print_help(prog_name: &str) {
    println!("Fast directory scanning and scraping tool

Usage: {} [OPTIONS] <uri|--uri-file <uri-file>|--uri <uri>>

Arguments:
  [uri]
          The URI of the host to scan, optionally supports basic auth with
          http://user:pass@host:port

Options:
  -u, --uri <uri>
          Additional hosts to scan [aliases: url]
  -U, --uri-file <uri-file>
          The filename of a file containing a list of URIs to scan - cookies and
          headers set will be applied to all URIs [aliases: url-file]
      --verb <http_verb>
          Specify which HTTP verb to use
           [default: get] [possible values: get, head, post]
  -w, --wordlist <wordlist>
          Sets which wordlist to use, defaults to dirble_wordlist.txt in the same
          folder as the executable
  -p, --prefixes <prefixes>...
          Provides comma separated prefixes to extend queries with
  -P, --prefix-file <prefix-file>
          The name of a file containing extensions to extend queries with, one
          per line
